window.AtlasCinema=(()=>{
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LESSONS=window.ATLAS_LESSONS;
const color={green:'#376d58',orange:'#d28a4f',red:'#bc625e',blue:'#6289ab',muted:'#74857b'};
let selected=0,index=0,playing=false,raf=0,last=0,elapsed=0,speed=1,animations=[],focus=false,manual=false,singleScene=false;
const duration=7200;
function stateAt(i){return Object.assign({},...LESSONS[selected].frames.slice(0,i+1).map(f=>f.state))}
function sourceFor(f){const file=window.ATLAS_DATA.files.find(x=>x.name===f.file);let pos=file.lines.findIndex(x=>x.includes(f.needle));if(pos<0)pos=0;const start=Math.max(0,pos-1),end=Math.min(file.lines.length,pos+3);return {pos:pos+1,lines:file.lines.slice(start,end).map((text,i)=>({number:start+i+1,text,active:start+i===pos}))}}
function mount(){stop();const lesson=LESSONS[selected];q('#app').innerHTML=`<div class="film-heading"><div><div class="film-eyebrow"><span></span> HỌC BẰNG CHUYỂN ĐỘNG</div><h1>Nhìn dữ liệu.<br class="phone-break"/> Hiểu cách code chạy.</h1><p>Không cần đọc cả sơ đồ cùng lúc. Xem một thao tác, nhìn giá trị đổi, rồi mở dòng code tương ứng.</p></div><button class="film-focus" id="film-focus">${focus?'↙ Thu gọn':'⤢ Chế độ tập trung'}</button></div><div class="lesson-selector"><label for="film-lesson">Chọn một câu chuyện</label><select id="film-lesson">${LESSONS.map((l,i)=>`<option value="${i}" ${i===selected?'selected':''}>${l.n}. ${l.name}</option>`).join('')}</select><span class="film-duration">${lesson.frames.length} cảnh · khoảng ${Math.round(lesson.frames.length*duration/1000)} giây</span><span class="film-concept">${lesson.concept}</span></div><section class="film-shell"><div class="film-topline"><span class="film-episode">${lesson.icon} <b>${lesson.name}</b></span><span id="film-scene-count"></span><span class="film-live"><i></i> DỮ LIỆU MINH HỌA</span></div><div class="film-board-scroll" id="film-board-scroll"><div class="film-board" id="film-board"></div><div class="film-start-overlay" id="film-start-overlay"><button id="film-start" aria-label="Bắt đầu xem animation"><span>▶</span><strong>Xem dữ liệu chuyển động</strong><small>Đi từng bước, giải thích ngay bên dưới</small></button></div></div><div class="film-narration" aria-live="polite"><span class="film-scene-tag" id="film-scene-tag"></span><h2 id="film-title"></h2><p id="film-caption"></p></div><div class="film-controls"><button class="film-icon" id="film-restart" title="Xem lại từ đầu" aria-label="Xem lại từ đầu">↺</button><button class="film-icon" id="film-prev" title="Cảnh trước" aria-label="Cảnh trước">←</button><button class="film-play" id="film-play">▶ Phát bài phim</button><button class="film-icon" id="film-next" title="Cảnh tiếp" aria-label="Cảnh tiếp">→</button><div class="film-scrub"><input type="range" min="0" max="${lesson.frames.length-1}" step="1" value="${index}" id="film-scrubber" aria-label="Chọn cảnh animation"><span class="film-time" id="film-time"></span></div><label class="film-speed">Tốc độ<select id="film-speed" aria-label="Tốc độ bài phim"><option value="0.75">Chậm 0,75×</option><option value="1" selected>Bình thường</option><option value="1.5">Nhanh 1,5×</option></select></label></div><div class="film-timeline" id="film-timeline">${lesson.frames.map((f,i)=>`<button data-film-step="${i}" title="${E(f.title)}"><span>${String(i+1).padStart(2,'0')}</span><b>${E(f.title)}</b><i></i></button>`).join('')}</div></section><div class="film-details"><article class="film-understand"><span class="film-label">ĐIỀU CẦN HIỂU Ở CẢNH NÀY</span><h3 id="film-takeaway"></h3><div class="film-change" id="film-change"></div><p class="film-footnote">Animation minh họa hành vi của code Python hiện tại. Không chạy Python thật và không thay đổi dữ liệu sinh viên.</p></article><article class="film-code"><div class="film-code-head"><span id="film-source-file"></span><button id="film-open-source">Mở code đầy đủ ↗</button></div><pre id="film-source"></pre><div id="film-source-note"></div></article></div><section class="film-library"><div><span class="film-label">KHÁM PHÁ THÊM</span><h2>Mỗi bài phim, một ý chính.</h2></div><div class="film-lessons">${LESSONS.map((l,i)=>`<button data-film-lesson="${i}" class="${i===selected?'active':''}"><span class="lesson-symbol">${l.icon}</span><span><small>BÀI ${l.n} · ${l.frames.length} CẢNH</small><strong>${l.name}</strong><em>${l.subtitle}</em></span><span class="lesson-arrow">↗</span></button>`).join('')}</div></section>`;
q('#film-lesson').onchange=e=>changeLesson(+e.target.value);qa('[data-film-lesson]').forEach(b=>b.onclick=()=>{changeLesson(+b.dataset.filmLesson);q('.film-heading').scrollIntoView({behavior:'smooth',block:'start'})});qa('[data-film-step]').forEach(b=>b.onclick=()=>jump(+b.dataset.filmStep));q('#film-start').onclick=()=>play();q('#film-play').onclick=()=>playing?pause():play();q('#film-prev').onclick=()=>jump(Math.max(0,index-1));q('#film-next').onclick=()=>jump(Math.min(lesson.frames.length-1,index+1));q('#film-restart').onclick=()=>{index=0;elapsed=0;manual=true;renderFrame();play()};q('#film-scrubber').oninput=e=>jump(+e.target.value);q('#film-speed').value=String(speed);q('#film-speed').onchange=e=>{speed=Number(e.target.value);animations.forEach(a=>a.playbackRate=speed)};q('#film-focus').onclick=()=>{focus=!focus;document.body.classList.toggle('theater-focus',focus);q('#film-focus').textContent=focus?'↙ Thu gọn':'⤢ Chế độ tập trung';};q('#film-open-source').onclick=()=>{const f=lesson.frames[index];const r=sourceFor(f);window.AtlasBridge.openCode(f.file,r.pos)};
renderFrame(false);if(manual)q('#film-start-overlay').hidden=true;}
function changeLesson(i){pause();selected=i;index=0;elapsed=0;manual=false;mount()}
function stop(){playing=false;cancelAnimationFrame(raf);animations.forEach(a=>a.cancel());animations=[];last=0;document.body.classList.remove('theater-focus');focus=false}
function pause(){playing=false;cancelAnimationFrame(raf);animations.forEach(a=>a.pause());if(q('#film-play'))q('#film-play').textContent='▶ Tiếp tục';last=0}
function play(){if(!q('#film-board'))return;manual=true;q('#film-start-overlay').hidden=true;if(index===LESSONS[selected].frames.length-1&&elapsed>=duration){index=0;elapsed=0;renderFrame()}q('.film-topline').scrollIntoView({behavior:'smooth',block:'start'});playing=true;singleScene=false;q('#film-play').textContent='Ⅱ Tạm dừng';animations.forEach(a=>a.play());last=0;raf=requestAnimationFrame(tick)}
function jump(i){pause();index=i;elapsed=0;manual=true;q('#film-start-overlay').hidden=true;renderFrame();singleScene=true;playing=true;last=0;q('#film-play').textContent='Ⅱ Tạm dừng';animations.forEach(a=>a.play());raf=requestAnimationFrame(tick);}
function tick(t){if(!playing)return;if(last)elapsed+=(t-last)*speed;last=t;const progress=Math.min(1,elapsed/duration);const current=q(`[data-film-step="${index}"] i`);if(current)current.style.width=(progress*100)+'%';if(elapsed>=duration){if(singleScene){pause();q('#film-play').textContent='▶ Phát tiếp';return;}if(index<LESSONS[selected].frames.length-1){index++;elapsed=0;renderFrame()}else{pause();q('#film-play').textContent='↺ Xem lại bài phim';q('#film-title').textContent='Bạn vừa xem xong: '+LESSONS[selected].name;q('#film-scene-tag').textContent='HOÀN THÀNH ✓';return;}}followFlight();raf=requestAnimationFrame(tick)}
function followFlight(){if(window.innerWidth>800)return;const f=LESSONS[selected].frames[index];if(!f.motion)return;const u=Math.min(1,elapsed/4400);const x=f.motion.from[0]+(f.motion.to[0]-f.motion.from[0])*u;const y=f.motion.from[1]+(f.motion.to[1]-f.motion.from[1])*u;const box=q('#film-board-scroll');if(box){box.scrollLeft=Math.max(0,x-box.clientWidth/2);box.scrollTop=Math.max(0,y-box.clientHeight/2)}}
function renderFrame(animate=true){const l=LESSONS[selected],f=l.frames[index],s=stateAt(index),prev=index?stateAt(index-1):{};animations.forEach(a=>a.cancel());animations=[];q('#film-title').textContent=f.title;q('#film-caption').textContent=f.caption;q('#film-scene-tag').textContent='CẢNH '+String(index+1).padStart(2,'0');q('#film-scene-count').textContent=`${index+1} / ${l.frames.length}`;q('#film-takeaway').textContent=f.why;q('#film-scrubber').value=index;q('#film-time').textContent=`Cảnh ${index+1} / ${l.frames.length}`;q('#film-prev').disabled=index===0;q('#film-next').disabled=index===l.frames.length-1;
qa('[data-film-step]').forEach(b=>{const i=+b.dataset.filmStep;b.classList.toggle('current',i===index);b.classList.toggle('past',i<index);b.querySelector('i').style.width=i<index?'100%':'0%'});
const ref=sourceFor(f);q('#film-source-file').textContent=f.file+' : '+ref.pos;q('#film-source').innerHTML=ref.lines.map(r=>`<span class="${r.active?'lit':''}"><i>${r.number}</i>${E(r.text)}</span>`).join('');const file=window.ATLAS_DATA.files.find(x=>x.name===f.file);q('#film-source-note').textContent=file.notes[ref.pos]||'';
const displayKey=k=>l.layout==='update'?({fe:'result.grade_fe',re:'result.grade_re',pendingFe:'fe · biến tạm',pendingRe:'re · biến tạm'}[k]||k):k;const displayValue=(k,v)=>typeof v==='number'&&(/fe|re/i.test(k))?v.toFixed(1):format(v);const changes=Object.entries(f.state).filter(([k,v])=>!['phase','check','gate','highlight','scan','objectReady','keys','parts','saved','loaded','filter','sorted','error','found','valid','line','items','object','order','active'].includes(k)&&JSON.stringify(prev[k])!==JSON.stringify(v));q('#film-change').innerHTML=changes.length?changes.slice(0,4).map(([k,v])=>`<div><code>${E(displayKey(k))}</code><span>${E(displayValue(k,prev[k]))}</span><b>→</b><strong>${E(displayValue(k,v))}</strong></div>`).join(''):`<div class="no-value-change">${E(s.check||s.gate||'Đang theo dõi đường đi của dữ liệu.')}</div>`;
q('#film-board').innerHTML=draw(l.layout,s,f);const svg=q('#film-board svg');if(animate){q('#film-title').animate([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:450});qa('#film-board .scene-pop').forEach((el,i)=>{const a=el.animate([{opacity:.3},{opacity:1}],{duration:650,delay:i*90,fill:'both'});animations.push(a)});qa('#film-board .cell-change').forEach(el=>{const a=el.animate([{fill:'#ffdc9d'},{fill:'#edf7e9'}],{duration:1700,fill:'both'});animations.push(a)});}
if(f.motion){const token=q('#flight-token');const m=f.motion;const dx=m.to[0]-m.from[0],dy=m.to[1]-m.from[1];token.style.transform=`translate(${m.from[0]}px,${m.from[1]}px)`;const a=token.animate([{transform:`translate(${m.from[0]}px,${m.from[1]}px)`,opacity:0,offset:0},{transform:`translate(${m.from[0]}px,${m.from[1]}px)`,opacity:1,offset:.12},{transform:`translate(${m.from[0]+dx*.45}px,${m.from[1]+dy*.45-35}px)`,opacity:1,offset:.5},{transform:`translate(${m.to[0]}px,${m.to[1]}px)`,opacity:1,offset:.83},{transform:`translate(${m.to[0]}px,${m.to[1]}px)`,opacity:0,offset:1}],{duration:4600,easing:'ease-in-out',fill:'forwards'});a.playbackRate=speed;animations.push(a)}
if(l.layout==='sort'&&s.sorted){qa('#film-board .sort-card').forEach(el=>{const key=el.dataset.key;const sourceX={N:50,F:370,P:690}[key],destX={P:50,F:370,N:690}[key];const a=el.animate([{transform:`translateX(${sourceX-destX}px)`},{transform:'translateX(0px)'}],{duration:2600,easing:'cubic-bezier(.2,.8,.2,1)',fill:'both'});a.playbackRate=speed;animations.push(a)})}
if(!playing)animations.forEach(a=>a.pause());if(window.innerWidth<=800){const box=q('#film-board-scroll');box.scrollLeft=f.motion?Math.max(0,f.motion.from[0]-box.clientWidth/2):0;}}
function format(v){if(v===undefined)return '—';if(v===null)return 'None';if(Array.isArray(v))return '['+v.join(', ')+']';return String(v)}
function text(x,y,str,size=19,fill='#334e43',weight=500,anchor='start',extra=''){return `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" font-weight="${weight}" text-anchor="${anchor}" ${extra}>${E(str)}</text>`}
function rect(x,y,w,h,fill='#fff',stroke='#dce5d8',r=15,extra=''){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" stroke="${stroke}" stroke-width="1.5" ${extra}/>`}
function tag(x,y,str,tone='green',w=170){const c=color[tone]||color.green;return rect(x,y,w,33,tone==='red'?'#fff0ec':tone==='orange'?'#fff5e4':'#eaf4e9',c,16)+text(x+w/2,y+22,str,15,c,600,'middle')}
function line(x1,y1,x2,y2,tone='green',dash=false){return `<path d="M${x1},${y1} L${x2},${y2}" fill="none" stroke="${color[tone]||color.green}" opacity=".45" stroke-width="2" marker-end="url(#arrow)" ${dash?'stroke-dasharray="7 7"':''}/>`}
function box(x,y,w,h,title,sub,active=false){return `<g class="scene-pop">${rect(x,y,w,h,active?'#f0f6e9':'#fff',active?'#8eb379':'#dce5d8')}${text(x+18,y+30,title,19,'#365844',650)}${text(x+18,y+54,sub,14,'#7e8d80',400)}</g>`}
function row(x,y,k,v,changed=false,w=260){if(typeof v==='number'&&(/fe|re/i.test(k)||/FE|RE/.test(k)))v=v.toFixed(1);return `${rect(x,y,w,37,changed?'#edf7e9':'#f6f8f2','transparent',6,changed?'class="cell-change"':'')}${text(x+12,y+25,k,15,'#82917e',400)}${text(x+w-12,y+25,format(v),18,changed?'#32794f':'#425b4c',600,'end')}`}
function checkline(s){return rect(220,392,580,37,'#f0f4e9','transparent',18)+text(510,417,s.check||s.gate||'Quan sát dữ liệu đi qua từng bước',17,'#607a52',500,'middle')}
function list(s,y=306){let out=text(28,y-13,'_students · list trong bộ nhớ',16,'#7e8d80',500);out+=rect(20,y,980,73,'#f2f5ec','#dae4d4',12);(s.items||[]).slice(0,4).forEach((id,i)=>{const x=40+i*243;out+=`<g class="scene-pop">${rect(x,y+12,220,49,s.highlight===id?'#e7f2de':'#fff',s.highlight===id?'#94b773':'#dce4d6',9,s.highlight===id?'class="cell-change"':'')}${text(x+10,y+42,'['+i+']',13,'#a2ac9b')}${text(x+45,y+42,id,18,'#49623e',600)}</g>`});return out}
function pipeline(s){let out=box(25,25,265,235,'① Nhập dữ liệu','Chuỗi từ console',s.phase==='input')+box(375,25,270,235,'② Validator','Chuẩn hóa & kiểm tra',String(s.phase).includes('valid'))+box(730,25,265,235,'③ Student object','Một sinh viên trong RAM',!!s.object);out+=text(45,130,s.input||'—',28,'#b8794b',650)+text(45,163,'kiểu: str',16,'#9a9f8b',400);out+=line(300,155,360,155)+line(655,155,715,155);out+=tag(395,122,s.gate||'Chờ kiểm tra','green',230);if(s.object){out+=row(744,100,'student_id',s.object.student_id,false,236)+row(744,141,'full_name',s.object.full_name,s.highlight==='full_name',236)+row(744,182,'status',s.object.status,false,236)}else out+=text(862,162,'Chưa được tạo',19,'#acb5a4',400,'middle');out+=list(s);return out}
function search(s){let out=text(35,43,'MÃ ĐANG TÌM',14,'#80907d',500)+text(35,78,s.target,28,'#3c7257',650);out+=text(570,47,'Biến student đi lần lượt qua từng phần tử',17,'#8e9984',400);s.items.forEach((id,i)=>{const x=35+i*325,active=s.scan===i;out+=`<g class="scene-pop">${rect(x,135,300,135,active?s.found?'#e9f5e0':'#fff5e6':'#fff',active?s.found?'#88b76c':'#dcaa68':'#dce5d8')}${text(x+20,163,'['+i+']  Student',16,'#96a18d',500)}${text(x+150,211,id,24,'#415e45',650,'middle')}${text(x+150,243,active?(s.found?'Đúng mã ✓':s.outcome||'Đang kiểm tra'):'Chưa xét',16,active?'#b88950':'#a5afa0',500,'middle')}</g>`;if(active)out+=tag(x+52,87,'student ↓',s.found?'green':'orange',195)});out+=line(182,290,182,323)+line(507,290,507,323)+line(832,290,832,323);out+=rect(270,324,480,53,'#edf3e7','#cedec3',12)+text(510,358,'Giá trị trả về: '+(s.returned||'chưa return'),22,'#5a7950',550,'middle');return out}
function result(s){let out=box(25,25,285,285,'Dữ liệu đầu vào','Biến của menu',s.phase==='fe'||s.phase==='re')+box(385,25,235,285,'Điều kiện','Chọn nhánh theo FE',false)+box(695,25,300,285,s.objectReady?'Result object':'Chưa tạo Result',s.objectReady?'Thuộc tính trong object':'Đang nhập vào biến menu',s.objectReady);out+=row(42,100,'MSSV',s.student,false,251)+row(42,145,'FE',s.raw||s.fe,s.phase==='fe',251)+row(42,190,'RE',s.re,s.phase==='re',251);out+=line(320,175,372,175)+line(630,175,682,175);out+=text(503,131,'FE đã có?',20,'#66815b',600,'middle')+text(503,173,s.fe===null?'Không: None':'Có: '+s.fe.toFixed(1),22,s.fe===null?'#b28b62':'#446d4e',600,'middle')+text(503,215,s.fe===null?'Không hỏi RE':s.fe>=5?'FE ≥ 5 → Pass':'FE < 5 → hỏi RE',17,'#829376',400,'middle');if(s.objectReady||['status-none','display','zero'].includes(s.phase)){out+=row(710,99,'grade_fe',s.fe,s.phase==='fe'||s.phase==='zero',269)+row(710,143,'grade_re',s.re,s.phase==='re',269);const status=s.status===null?'Chưa có điểm':s.status;out+=tag(719,208,status,s.status==='Fail'?'orange':'green',250);}else{out+=text(845,158,'Chưa có object',23,'#a2ad96',500,'middle')+text(845,200,'FE / RE đang ở biến bên trái',15,'#a2ad96',400,'middle');}out+=rect(130,330,760,44,'#f3f5ee','transparent',10)+text(510,358,s.items?.length?'_results = [ Result #1 ] · chưa ghi file':'_results = [ ] · đang chuẩn bị dữ liệu',20,'#7e8e70',500,'middle');return out}
function update(s){let out=box(25,25,278,295,'Trước khi sửa','Giá trị cũ để đối chiếu')+box(370,25,278,295,'Biến tạm','Validate trước, chưa gán',s.phase==='temp')+box(715,25,280,295,'Object hiện tại','Chỉ đổi sau khi hợp lệ',s.phase.startsWith('commit'));out+=row(43,108,'FE cũ',s.oldFe,false,241)+row(43,158,'RE cũ',s.oldRe,false,241);out+=row(388,108,'fe',s.pendingFe,s.phase==='temp',241)+row(388,158,'re',s.pendingRe,s.phase==='clear',241);out+=row(733,108,'grade_fe',s.fe,s.phase==='commit-fe',243)+row(733,158,'grade_re',s.re,s.phase==='commit-re',243);out+=line(310,175,355,175)+line(655,175,700,175);out+=tag(745,238,'status: '+s.status,'green',220);out+=text(509,354,'Điểm sai → raise trước khi đụng vào object cũ',20,'#a38d6a',500,'middle');return out}
function sort(s){let out=text(30,40,'LIST GỐC GIỮ NGUYÊN: [ None, Fail, Pass ]',19,'#809178',500);const labels={N:'Chưa có điểm',F:'Fail',P:'Pass'},keys={N:'""',F:'"Fail"',P:'"Pass"'};s.order.forEach((id,i)=>{const x=35+i*325;out+=`<g class="sort-card" data-key="${id}">${rect(x,105,300,155,s.filter&&id!=='P'?'#f7f7f4':id==='P'?'#eef6e6':'#fff',id==='P'?'#a5be8a':'#dce5d8')}${text(x+20,138,'Result '+id,16,'#8a9981',500)}${text(x+150,184,labels[id],26,s.filter&&id!=='P'?'#c2c7ba':'#486443',600,'middle')}${text(x+150,228,s.keys?'key = '+keys[id]:'Chưa tính key',18,'#aa936c',400,'middle')}${s.filter&&id!=='P'?text(x+150,293,'Không lấy vào list lọc',15,'#bcaa8c',400,'middle'):''}</g>`});out+=rect(200,325,620,53,'#edf4e4','#cfddc2',12)+text(510,359,s.filter?'passed_results → [ Result P ]':s.sorted?'List mới → [ Pass, Fail, None ]':'Kết quả trả về: đang chuẩn bị',23,'#647e50',600,'middle');return out}
function file(s){let out=box(25,25,280,260,s.loaded?'Result được phục hồi':'Result trong RAM','Dữ liệu có kiểu số',s.phase==='parse')+box(380,25,260,260,s.parts?'split → parts':'to_file_line()','Chuyển đổi biểu diễn',s.phase==='serialize'||s.phase==='split')+box(715,25,280,260,'results.txt','Chuỗi văn bản UTF-8',s.saved);out+=row(42,103,'FE · float',s.fe,false,245)+row(42,151,'RE · float',s.re,false,245)+row(42,199,'credits · int',3,false,245);out+=line(315,158,367,158,s.loaded?'orange':'green')+line(650,158,702,158,s.parts?'orange':'green');out+=text(510,140,s.parts?'["SE…", "PFP191", …]':s.line?'"…|4.0|5.0|Pass"':'object → chuỗi',17,'#8c916f',500,'middle')+text(510,190,s.parts?'Các phần tử đều là str':'8 cột, phân cách bằng |',16,'#99a189',400,'middle');out+=text(855,120,s.saved?'▤ Dòng đã ghi':'▤ Chưa ghi',23,s.saved?'#528455':'#a8b19d',600,'middle')+text(855,173,'"3"   "4.0"   "5.0"',18,'#b18c5a',500,'middle');const parts=['SE211528','PFP191','Tên môn','Fall2026','3','4.0','5.0','Pass'];parts.forEach((t,i)=>{const x=25+i*124;out+=rect(x,328,120,48,s.parts?'#fff4e3':'#f1f5eb',s.parts?'#e1c799':'#dae4d1',8)+text(x+60,358,t,i<2?14:16,'#7d8e6f',500,'middle')});return out}
function validation(s){let out=box(25,25,280,270,'input()','Người dùng nhập chuỗi',s.phase==='raw'||s.phase==='correct')+box(380,25,260,270,'validate_score','Kiểm tra khoảng 0–10',true)+box(715,25,280,270,s.error?'Bị chặn':'Giá trị trả về',s.error?'Chưa đổi object':'Đã kiểm tra hợp lệ',s.valid);out+=text(165,172,s.input,36,'#b88350',650,'middle')+text(165,213,'kiểu ban đầu: str',17,'#9ba48e',400,'middle');out+=text(510,145,'0 ≤ score ≤ 10 ?',23,'#708362',600,'middle')+tag(405,182,s.error?'Sai ✕':s.valid?'Đúng ✓':'Đang kiểm tra',s.error?'red':'green',210);out+=line(315,165,365,165)+line(650,165,700,165,s.error?'red':'green');out+=text(855,157,s.error?'ValueError':s.valid?'4.0':'Chưa trả về',s.error?24:29,s.error?'#b6605c':'#628759',600,'middle')+text(855,205,s.error?'Thông báo rồi nhập lại':s.valid?'kiểu trả về: float':'Object chưa thay đổi',17,'#9aa58e',400,'middle');out+=`<path d="M850 302 Q850 355 510 355 Q165 355 165 300" fill="none" stroke="#daa66b" stroke-width="2" stroke-dasharray="8 6" marker-end="url(#arrow)"/>`+text(510,344,'except bắt lỗi → vòng while hỏi lại',18,'#bc975e',500,'middle');return out}
function draw(layout,s,f){const content=({pipeline,search,result,update,sort,file,validation}[layout])(s);let flight='';if(f.motion){const m=f.motion,c=color[m.tone]||color.green,w=Math.max(145,Math.min(300,m.label.length*10+30));flight=`<g id="flight-token"><rect x="${-w/2}" y="-24" width="${w}" height="48" rx="12" fill="${c}" stroke="#ffffff" stroke-width="3" filter="url(#shadow)"/>${text(0,7,m.label,18,'#fff',650,'middle')}<circle r="4" cx="${-w/2+12}" cy="0" fill="#fff" opacity=".55"/></g>`}return `<svg viewBox="0 0 1020 445" role="img" aria-label="${E(f.title)}" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".75" fill="#d9e1d0"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="5" stdDeviation="5" flood-color="#263f29" flood-opacity=".18"/></filter><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="none" stroke="#90a47f" stroke-width="1.5"/></marker></defs><rect width="1020" height="445" fill="url(#grid)"/>${content}${checkline(s)}${flight}</svg>`}
document.addEventListener('keydown',e=>{if(!q('#film-board')||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();playing?pause():play()}if(e.key==='ArrowRight'){e.preventDefault();jump(Math.min(index+1,LESSONS[selected].frames.length-1))}if(e.key==='ArrowLeft'){e.preventDefault();jump(Math.max(index-1,0))}});
return {mount,stop};
})();
